"""Native reference exports and October 11 ordinary-enemy route checks."""
from pathlib import Path
from playwright.sync_api import sync_playwright
import shoot,json,sys,base64
ROOT=Path(__file__).resolve().parents[1]
OUT=ROOT/'_shots/playthrough_1011/routes';OUT.mkdir(parents=True,exist_ok=True)
REF=ROOT/'_ART_SOURCES/playthrough_1011/reference';REF.mkdir(parents=True,exist_ok=True)
checks=[];errors=[]
def check(name,passed,data=None):
 checks.append(dict(name=name,passed=bool(passed),data=data));print(('PASS ' if passed else 'FAIL ')+name+((' '+json.dumps(data)) if not passed else ''),flush=True)
port,stop=shoot.serve(str(ROOT))
try:
 with sync_playwright() as pw:
  br=pw.chromium.launch(args=['--mute-audio']);p=br.new_page(viewport=dict(width=1280,height=1000));p.set_default_timeout(120000)
  p.on('pageerror',lambda e:errors.append(str(e)))
  p.on('console',lambda m:errors.append(m.text[:650]) if m.type=='error' or 'draw error' in m.text else None)
  p.goto(f'http://127.0.0.1:{port}');p.wait_for_function('window.__bofFrames>4');p.evaluate(shoot.TRAP_RAF)
  def scene(n):
   p.evaluate(shoot.SETUP,dict(state='PLAY',stage=n,pilot='maverick',invuln=True))
   p.wait_for_function('n=>{stageLoadTick();return stageLoadInfo(n).ready}',arg=n,polling=50)
   p.evaluate('''()=>{BOFCinematicDirector.cancel();story=fb2Talk=s6Opening=special=null;H3.release=false;H3.ending=null;stagePlan=[];enemies=[];pBullets=[];eBullets=[];powerups=[];boss=subBoss=null;bossActive=subBossActive=false;subBossDone=true;player.invuln=1e9;camX=0;diffKey='furious';DIFF=difficultyForRun('arcade','furious');}''')
  def ticks(n):
   for i in range(0,n,20):
    err=p.evaluate(shoot.STEP,min(20,n-i))
    if err:errors.append(err)
    p.wait_for_timeout(4)
  def snap(name):
   p.evaluate('()=>{story=fb2Talk=null;ctx.setTransform(SS,0,0,SS,0,0);drawWorld(0);drawHUDStrip(hudctx);fb9HudSplit();window.__bofFit();}')
   p.screenshot(path=str(OUT/(name+'.png')))
  scene(5);p.evaluate("spawnSubBoss__inner('chaosharrier')")
  p.wait_for_function("()=>['ch2_gun_0','ship_cole','ship_maverick','nthr_blue_0'].map(k=>XART.rdy(k)).every(Boolean)",polling=50)
  for key in ['ch2_gun_0','ship_cole','ship_maverick','nthr_blue_0']:
   raw=p.evaluate('''key=>{const im=XART.get(key),c=document.createElement('canvas');c.width=im.width;c.height=im.height;c.getContext('2d').drawImage(im,0,0);return c.toDataURL();}''',key)
   (REF/(key+'.png')).write_bytes(base64.b64decode(raw.split(',')[1]))
  ticks(120)
  p.evaluate("()=>{const b=subBoss;b._chState='idle';b._chVisible=true;b._chT=0;b._chCollision=true;b._chAlpha=1;b._chScale=1;b.enter=false;b.x=240;b.y=150;b._drawY=b.y;b._chTell=null;b._chActiveLaser=null;b._chWarp=null;b._chCD=10;}")
  snap('chaos-harrier')
  check('Harrier cannon uses the generated sixteen-pose bank',p.evaluate("pt11Ready('harrier_cannon')&&(PT11.draws.harrier_cannon||0)>0"))
  p.evaluate("()=>{window.harrierSeen={states:[],beams:0,shots:0};subBoss._chCd=0;subBoss._chWarpCount=0;subBoss._chStandLeft=0;}")
  for i in range(120):
   p.evaluate('''()=>{for(let i=0;i<30;i++){chaosHarrierUpdate(subBoss,1/60);const b=subBoss;if(!harrierSeen.states.includes(b._chState))harrierSeen.states.push(b._chState);harrierSeen.beams=Math.max(harrierSeen.beams,Number(!!b._chActiveLaser));harrierSeen.shots=Math.max(harrierSeen.shots,eBullets.length);}}''');p.wait_for_timeout(4)
  q=p.evaluate('harrierSeen')
  check('Harrier naturally uses warp, plasma, missiles and sequential lasers without the crossed rotor attack',all(s in q['states'] for s in ['warpout','warpin','plasma','missile','side','beam']) and 'cross' not in q['states'] and q['beams']==1 and q['shots']>0,q)
  p.evaluate("()=>{chaosHarrierFinish(subBoss);subBoss._chVisible=true;subBoss._chCollision=true;subBoss._chAlpha=subBoss._chScale=1;subBoss.x=240;subBoss.y=150;}")
  q=p.evaluate('''()=>{const b=subBoss,parts=pt11HarrierGuns(b),g=parts[0],q=pt11HarrierGunPose(b,g),other=parts[1].hp;b.hp=b.maxhp;hitSubBoss(g.hp+1,q.x,q.y);eBullets=[];chaosHarrierShot(b,'sidelaser',g.id,Math.PI/2,5);return{left:g.dead,right:parts[1].hp===other,shots:eBullets.length,targets:retinaBossTargets(b).map(t=>t.kind)};}''')
  check('Broken Harrier cannon stops firing independently of the other module',q['left'] and q['right'] and q['shots']==0,q);snap('harrier-left-cannon-destroyed')
  q=p.evaluate('''()=>{const b=subBoss;b.y=205;player.y=70;for(let i=0;i<180;i++)chaosHarrierOrbit(b,1/60);return{y:b.y,top:viewTopY(),contact:pt11HarrierContact(b,b.x+b.w*.48,b.y+b.h*.45)};}''')
  check('Harrier clears the upper route and has no invisible rectangular corner collision',q['y']<145 and not q['contact'],q)
  q=p.evaluate('''()=>{const b=subBoss;b._chCollision=true;b._noHit=false;b.enter=false;b.hp=b.maxhp*.3;hitSubBoss(1,b.x,b.y);return{live:!b.dead,hp:b.hp,max:b.maxhp};}''')
  check('Chaos Harrier stays alive below thirty percent HP',q['live'] and q['hp']>0,q)
  scene(8);p.evaluate("window.heavy=spawnEnemy('pt11frostcarrier',240,-150,{})")
  p.wait_for_function("()=>FB1002_FROST_NAMES.map(n=>XART.rdy(FB1002_ART[n].key)).every(Boolean)",polling=50)
  ticks(320);snap('legacy-frost-heavy')
  q=p.evaluate('''()=>({hp:heavy.hp,parts:heavy._mr27.parts.length,bar:subBossActive,enter:heavy.enter,mode:heavy._er26.mode,skin:heavy._mr27.skin,draws:heavy._mr27.draws})''')
  check('Original ice hull fights as a durable modular Stage 8 heavy without a miniboss slot',q['hp']>=350 and q['parts']==4 and not q['bar'] and not q['enter'] and q['draws']>0 and q['skin']=='frost1002',q)
  q=p.evaluate('''()=>{const b=heavy,p=mr27Part(b,'gunL'),s=mr27Shape(b,'gunL'),other=mr27Part(b,'gunR').hp;_dmgBullet={x:s.x,y:s.y};hitEnemy(b,p.hp+1);_dmgBullet=null;return{broken:p.dead,other:mr27Part(b,'gunR').hp===other};}''')
  check('Stage 8 heavy cannon damage follows the projectile contact',q['broken'] and q['other'],q);snap('legacy-frost-cannon-broken')
  ticks(400);check('Stage 8 heavy advances its native attack book',p.evaluate('heavy._er26.history.length>=3'))
  p.evaluate('heavy._pt11Age=35.1');ticks(500)
  check('Surviving heavy leaves without holding the stage route',p.evaluate('heavy.dead'))
  scene(6)
  check('Removed yellow Storm Buoy cannot be spawned by legacy waves',p.evaluate("spawnEnemy('s6buoy',240,100,{})===null"))
  p.evaluate('''()=>{groundTargetingFx=[];window.jet={x:200,y:110,hp:100,_mission29:{n:2,targetOffset:0}};missionBomb(jet);window.bombTest=groundTargetingFx.at(-1);}''')
  p.evaluate('groundTargetingTick(1.3)');snap('bomb-warning-before-release')
  check('Bomb stays attached until the incoming warning finishes',p.evaluate('!bombTest._pt11Released&&!bombTest.impact'))
  p.evaluate('jet.x=260;groundTargetingTick(.2)');snap('bomb-release')
  check('Bomb releases from the aircraft after its full warning',p.evaluate('bombTest._pt11Released&&bombTest._jetBomb.x===260&&!bombTest.impact'))
  p.evaluate('groundTargetingTick(.6)');check('Bomb impacts after its separate flight interval',p.evaluate('bombTest.impact'))
  scene(7)
  p.evaluate('''()=>{window.ramShots=[];window.ram=spawnEnemy('mm1003_hellram',340,30,{});window.oldMMShot=mm1003Shot;mm1003Shot=function(e,x,y,a){if(e===ram)ramShots.push({x,y,a,t:e._mm1003.t});return oldMMShot.apply(this,arguments);};player.x=240;player.y=420;}''')
  ticks(500);snap('hellram-complete-salvo')
  q=p.evaluate('''()=>({history:ram._mm1003.history.map(q=>q.phase),shots:ramShots.length,first:ramShots[0]?.t,finite:ramShots.every(q=>Number.isFinite(q.x+q.y+q.a))})''')
  check('Hellram completes its warned charge, retreat and aimed six-round salvo',all(k in q['history'] for k in ['tell','dash','backstep','fire','recover']) and q['shots']>=6 and q['finite'] and q['first']<7,q)
  p.evaluate('()=>{mm1003Shot=oldMMShot;}')
  scene(7);p.evaluate("()=>{spawnSubBoss__inner('dualscoopdredger');s7mInit(subBoss);subBoss.enter=false;subBoss.y=145;subBoss._drawY=145;subBoss._s7mod.drop=0;s7mSet(subBoss,'pressure-salvo');window.pressureShots=[];window.oldPressure=s7mShot;s7mShot=function(b,x,y){pressureShots.push({x,y,ports:s7mLive(b._s7mod,'gun').map(p=>s7mMuzzle(b,p.id))});return oldPressure.apply(this,arguments);};}")
  p.wait_for_function('()=>{s7mWarm();return XART.rdy("s7m_tank")}');ticks(25);snap('toxic-pressure-warning');ticks(65);snap('toxic-pressure-salvo')
  q=p.evaluate('''()=>({count:pressureShots.length,mounted:pressureShots.every(q=>q.ports.some(p=>Math.hypot(p.x-q.x,p.y-q.y)<.01)),mode:subBoss._s7mod.mode})''')
  check('Tank pressure salvo emits every round from a living physical cannon',q['count']>=9 and q['mounted'],q)
  p.evaluate('()=>{s7mShot=oldPressure;}')
  check('No page or console errors',not errors,errors);br.close()
finally:stop()
report=dict(passed=sum(q['passed'] for q in checks),failed=sum(not q['passed'] for q in checks),checks=checks,errors=errors)
(OUT/'report.json').write_text(json.dumps(report,indent=2),encoding='utf-8');print(json.dumps(report),flush=True)
sys.exit(1 if report['failed'] else 0)
